// KAAL physical layer against golden vectors generated by the Python prototype (tests/kaal/gen_golden.py).
#include "dect2/kaal/kaal_fec.h"
#include "dect2/kaal/kaal_phy.h"
#include "kaal_golden.h"
#include <cmath>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>
using namespace dect2::kaal;
#include "../common/test_util.h"

static std::vector<uint8_t> fromHex(const char* h, size_t nbits) {
    std::vector<uint8_t> b(nbits);
    for (size_t i = 0; i < nbits; i++) {
        const char c = h[i / 8 * 2], d = h[i / 8 * 2 + 1];
        const int hi = c <= '9' ? c - '0' : c - 'a' + 10, lo = d <= '9' ? d - '0' : d - 'a' + 10;
        b[i] = (uint8_t)(((hi << 4 | lo) >> (7 - i % 8)) & 1);
    }
    return b;
}

int main() {
    {   // interleaver permutation reproduces the Python one exactly, and the inverse undoes it
        const std::vector<uint32_t> p = interleavePerm(2560), inv = interleavePermInv(2560);
        size_t bad = 0;
        for (size_t i = 0; i < 2560; i++) bad += p[i] != G_PERM2560[i];
        CHECK(bad == 0, "perm differs in %zu positions", bad);
        size_t badInv = 0;
        for (size_t i = 0; i < 2560; i++) badInv += inv[p[i]] != i;
        CHECK(badInv == 0, "inverse wrong in %zu positions", badInv);
        std::vector<uint8_t> x(2560);
        for (size_t i = 0; i < x.size(); i++) x[i] = (uint8_t)((i * 5 + i / 7) & 1);
        const std::vector<uint8_t> y = interleave(x);
        std::vector<float> s(2560);
        for (size_t i = 0; i < s.size(); i++) s[i] = y[i] ? -1.f : 1.f;
        const std::vector<float> z = deinterleave(s);
        size_t badRt = 0;
        for (size_t i = 0; i < x.size(); i++) badRt += (z[i] < 0) != (x[i] != 0);
        CHECK(badRt == 0, "interleave round trip: %zu wrong", badRt);
    }
    {   // LDPC encoding of the fixed message
        const std::vector<uint8_t> msg = fromHex(G_MSG_HEX, 320), want = fromHex(G_CODEWORD_HEX, 640);
        std::vector<uint8_t> cw(640);
        ldpcEncode(msg.data(), cw.data());
        size_t bad = 0;
        for (int i = 0; i < 640; i++) bad += cw[i] != want[i];
        CHECK(bad == 0, "codeword differs in %zu bits", bad);
        CHECK(std::fabs(ldpcSyndromeScore([&] { static float l[640]; for (int i = 0; i < 640; i++) l[i] = cw[i] ? -1.f : 1.f; return l; }()) - 1.f) < 1e-6, "codeword does not satisfy the checks");
        // old convolutional encoder
        const std::vector<uint8_t> conv = convEncode(msg.data(), 64), cwant = fromHex(G_CONV_HEX, 128);
        CHECK(conv == cwant, "conv encoder mismatch");
    }
    {   // 16-QAM mapping and soft demap
        const std::vector<uint8_t> qb = fromHex(G_QBITS_HEX, 64);
        const std::vector<cf> sy = qam16Map(qb.data(), 64);
        int bad = 0;
        double pw = 0;
        for (int i = 0; i < 16; i++) {
            bad += (int)std::lround(sy[i].real() * std::sqrt(10.f)) != G_QLEVELS[i][0] || (int)std::lround(sy[i].imag() * std::sqrt(10.f)) != G_QLEVELS[i][1];
            pw += std::norm(sy[i]);
        }
        CHECK(sy.size() == 16 && bad == 0, "qam map: %d wrong", bad);
        std::vector<cf> ns(8);
        for (int i = 0; i < 8; i++) ns[i] = cf((float)(G_NOISY[i][0] / std::sqrt(10.0)), (float)(G_NOISY[i][1] / std::sqrt(10.0)));
        const std::vector<float> l = qam16DemapSoft(ns.data(), 8, (float)G_NOISE_VAR);
        double worst = 0;
        for (int i = 0; i < 32; i++) worst = std::fmax(worst, std::fabs(l[i] - G_LLR[i]));
        CHECK(worst < 2e-3, "soft demap worst error %g", worst);
        // noiseless symbols demap to the right hard bits
        const std::vector<float> h = qam16DemapSoft(sy.data(), 16, 0.1f);
        int hb = 0;
        for (int i = 0; i < 64; i++) hb += (h[i] < 0) != (qb[i] != 0);
        CHECK(hb == 0, "noiseless demap: %d wrong bits", hb);
    }
    {   // RRC taps and sweep template
        const std::vector<double> t = rrcTaps();
        CHECK((int)t.size() == G_RRC_N, "rrc length %zu", t.size());
        double e = 0, worst = 0;
        for (double v : t) e += v * v;
        for (int i = 0; i < 8; i++) worst = std::fmax(worst, std::fabs(t[i] - G_RRC_HEAD[i]));
        worst = std::fmax(worst, std::fabs(t[t.size() / 2] - G_RRC_MID));
        CHECK(std::fabs(e - 1.0) < 1e-9 && worst < 1e-7, "rrc energy %g worst %g", e, worst);
        const std::vector<cf> sw = sweepTemplate(48000);
        double sworst = 0;
        for (int k = 0; k < 4; k++) {
            const size_t i = (size_t)G_SWEEP_IDX[k][0];
            sworst = std::fmax(sworst, std::fabs(sw[i].real() - G_SWEEP_IDX[k][1]) + std::fabs(sw[i].imag() - G_SWEEP_IDX[k][2]));
        }
        CHECK(sworst < 1e-3, "sweep worst %g", sworst);
        const std::vector<cf> pre = preamble();
        double pp = 0;
        for (const cf& c : pre) pp += std::norm(c);
        CHECK(pre.size() == 32 && std::fabs(pp / 32 - 1.0) < 1e-6, "preamble power");
    }
    {   // encode, flip bits, decode
        const std::vector<uint8_t> msg = fromHex(G_MSG_HEX, 320);
        std::vector<uint8_t> cw(640), dec(320);
        ldpcEncode(msg.data(), cw.data());
        float llr[640];
        for (int i = 0; i < 640; i++) llr[i] = cw[i] ? -4.f : 4.f;
        for (int i = 0; i < 24; i++) llr[G_FLIPS[i]] = -llr[G_FLIPS[i]];
        int iters = 0;
        const bool ok = ldpcDecode(llr, dec.data(), kLdpcIters, kLdpcAlpha, &iters);
        CHECK(ok && dec == msg, "decode with 24 flips: ok=%d after %d iterations", (int)ok, iters);
        // clean input stops at once
        for (int i = 0; i < 640; i++) llr[i] = cw[i] ? -4.f : 4.f;
        CHECK(ldpcDecode(llr, dec.data(), kLdpcIters, kLdpcAlpha, &iters) && iters == 0 && dec == msg, "clean decode iters %d", iters);
        // all-zero message has an all-zero codeword
        std::vector<uint8_t> z(320, 0), zc(640, 1);
        ldpcEncode(z.data(), zc.data());
        int ones = 0;
        for (uint8_t b : zc) ones += b;
        CHECK(ones == 0, "zero message codeword has %d ones", ones);
    }
    return testSummary("kaal_phy");
}
